<?php
require_once __DIR__.'/../includes/config.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['admin_id'])){header('Location: admin-login.php');exit;}
function bh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='setting'){
  $key=trim($_POST['key']??'');$value=trim($_POST['value']??'');
  if($key!==''){$s=$conn->prepare('INSERT INTO business_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');if($s){$s->bind_param('ss',$key,$value);$s->execute();$s->close();$msg='Business setting saved.';}else $err='Run database/humsafar_business_upgrade.sql first.';}
 }elseif($action==='coupon'){
  $code=strtoupper(trim($_POST['code']??''));$type=$_POST['discount_type']??'percent';$value=(float)($_POST['discount_value']??0);$min=(float)($_POST['minimum_order']??0);$expiry=trim($_POST['expires_at']??'');
  if($code==='')$err='Coupon code is required.';else{$s=$conn->prepare('INSERT INTO coupons(code,discount_type,discount_value,minimum_order,expires_at,is_active) VALUES(?,?,?,?,?,1)');if($s){$s->bind_param('ssd ds',$code,$type,$value,$min,$expiry);$s->execute();$s->close();$msg='Coupon created.';}else $err='Run database/humsafar_business_upgrade.sql first.';}
 }elseif($action==='support'){
  $id=(int)$_POST['ticket_id'];$status=$_POST['status']??'in_progress';$reply=trim($_POST['reply']??'');$s=$conn->prepare('UPDATE support_tickets SET status=?,admin_reply=? WHERE id=?');if($s){$s->bind_param('ssi',$status,$reply,$id);$s->execute();$s->close();$msg='Support ticket updated.';}else $err='Support table is not installed.';
 }
}
$settings=[];$q=$conn->query('SELECT setting_key,setting_value FROM business_settings ORDER BY setting_key');if($q)while($r=$q->fetch_assoc())$settings[]=$r;
$coupons=[];$q=$conn->query('SELECT * FROM coupons ORDER BY id DESC LIMIT 30');if($q)while($r=$q->fetch_assoc())$coupons[]=$r;
$tickets=[];$q=$conn->query("SELECT * FROM support_tickets WHERE status NOT IN ('closed','resolved') ORDER BY id DESC LIMIT 30");if($q)while($r=$q->fetch_assoc())$tickets[]=$r;
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Management</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>body{margin:0;background:#f7f7f9;font-family:Segoe UI,Arial;color:#222}.page{margin-left:218px;padding:30px}.wrap{max-width:1150px}.title{font-size:30px;font-weight:900;margin:0}.sub{color:#777}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:22px}.card{background:#fff;border:1px solid #f0dfe6;border-radius:15px;padding:20px;box-shadow:0 5px 18px #00000008}.wide{grid-column:1/-1}.field{margin:10px 0}.field label{display:block;font-size:11px;font-weight:800;margin-bottom:5px}.input,select,textarea{width:100%;padding:10px;border:1px solid #ddd;border-radius:8px;box-sizing:border-box;font:inherit}.btn{border:0;background:#ed0038;color:#fff;padding:10px 16px;border-radius:8px;font-weight:800;cursor:pointer}.msg{padding:11px;border-radius:8px;margin:15px 0;background:#eaf8ef;color:#176c36}.err{background:#fff0f3;color:#a0002d}.table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{text-align:left;padding:9px;border-bottom:1px solid #eee}.pill{padding:4px 8px;border-radius:20px;background:#fff0f4;color:#ed0038;font-size:10px;font-weight:800}@media(max-width:900px){.page{margin-left:0}.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><?php include __DIR__.'/admin-sidebar.php';?><main class="page"><div class="wrap"><h1 class="title">Business Management</h1><p class="sub">Commission, promotions, support and operational controls.</p><?php if($msg):?><div class="msg"><?=bh($msg)?></div><?php endif;?><?php if($err):?><div class="msg err"><?=bh($err)?></div><?php endif;?><div class="grid"><section class="card"><h3>Business Settings</h3><form method="post"><input type="hidden" name="action" value="setting"><div class="field"><label>Setting</label><select name="key"><option value="restaurant_commission_percent">Restaurant Commission %</option><option value="rider_base_payout">Rider Base Payout</option><option value="delivery_fee">Delivery Fee</option><option value="currency">Currency</option></select></div><div class="field"><label>Value</label><input class="input" name="value" required></div><button class="btn">Save Setting</button></form></section><section class="card"><h3>Create Coupon</h3><form method="post"><input type="hidden" name="action" value="coupon"><div class="field"><label>Code</label><input class="input" name="code" placeholder="HUMSAFAR20" required></div><div class="field"><label>Discount</label><select name="discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed PKR</option></select></div><div class="field"><input class="input" name="discount_value" type="number" step="0.01" placeholder="20" required></div><div class="field"><label>Minimum Order</label><input class="input" name="minimum_order" type="number" step="0.01" value="0"></div><div class="field"><label>Expiry</label><input class="input" name="expires_at" type="datetime-local"></div><button class="btn">Create Coupon</button></form></section><section class="card"><h3>Installed Settings</h3><?php foreach($settings as $s):?><p><b><?=bh($s['setting_key'])?></b><br><span class="pill"><?=bh($s['setting_value'])?></span></p><?php endforeach;?></section><section class="card wide"><h3>Coupons</h3><table class="table"><tr><th>Code</th><th>Type</th><th>Value</th><th>Minimum</th><th>Expiry</th><th>Status</th></tr><?php foreach($coupons as $c):?><tr><td><b><?=bh($c['code'])?></b></td><td><?=bh($c['discount_type'])?></td><td><?=bh($c['discount_value'])?></td><td>PKR <?=bh($c['minimum_order'])?></td><td><?=bh($c['expires_at'])?></td><td><?=((int)$c['is_active']?'Active':'Off')?></td></tr><?php endforeach;if(!$coupons):?><tr><td colspan="6">No coupons yet.</td></tr><?php endif;?></table></section><section class="card wide"><h3>Open Support Tickets</h3><?php foreach($tickets as $t):?><form method="post" style="border-bottom:1px solid #eee;padding:12px 0"><input type="hidden" name="action" value="support"><input type="hidden" name="ticket_id" value="<?=bh($t['id'])?>"><b>#<?=bh($t['id'])?> · <?=bh($t['subject'])?></b> <span class="pill"><?=bh($t['role'])?></span><p><?=nl2br(bh($t['message']))?></p><select name="status"><option>in_progress</option><option>resolved</option><option>closed</option></select><textarea name="reply" placeholder="Admin reply" style="margin:8px 0"></textarea><button class="btn">Update Ticket</button></form><?php endforeach;if(!$tickets):?><p>No open tickets.</p><?php endif;?></section></div></div></main></body></html>